package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.support.StaticListableBeanFactory;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** 实际Mapper/READ_COMMITTED类代理事务，固定调试版本与Agent单一绑定；无外部服务。 */
class WorkflowDebugPersistenceTest extends WorkflowDebugTestFixture {
    @Test void ordinaryBuildSavesExactlyOnceAndDoesNotSelectLatestBusinessVersion() {
        var agent=createAgent(canvas());long wf=agent.getLongValue("workflowId");var normal=workflows.createVersion(wf,space,0L,JSONObject.of("name","v1"));long selected=normal.getLongValue("id");var graph=canvas();graph.put("opaqueNull",null);String beforeConfig=agentsMapper.find(agent.getLongValue("id")).getConfigJson();
        var built=workflows.debugBuild(wf,space,1L,buildBody(agent,graph),"ordinary",null,"ordinary_save_key");var receipt=receipt(built);var version=workflowMapper.version(Long.parseLong(receipt.getString("workflowVersionId")));
        assertEquals("2",built.get("revision"));assertEquals("2",receipt.get("snapshotRevision"));assertEquals(2,workflowMapper.find(wf).getRevision());assertEquals(selected,workflowMapper.find(wf).getLatestVersionId());assertEquals(2,agentsMapper.find(agent.getLongValue("id")).getRevision());var afterConfig=JSON.parseObject(agentsMapper.find(agent.getLongValue("id")).getConfigJson());assertEquals(JSON.parseObject(beforeConfig).getJSONObject("futureConfig"),afterConfig.getJSONObject("futureConfig"));assertTrue(afterConfig.getJSONObject("futureConfig").containsKey("nullValue"));assertNull(afterConfig.getJSONObject("futureConfig").get("nullValue"));assertEquals(new JSONArray(),afterConfig.getJSONArray("inputExample"));assertTrue(JSON.parseObject(version.getCanvasJson()).containsKey("opaqueNull"));
        assertEquals("ordinary",version.getDebugMode());assertEquals(42L,version.getDebugOwnerUserId());assertEquals(agent.getLong("id"),version.getDebugAgentId());assertEquals(1,workflowMapper.countVersions(wf));assertEquals(selected,workflowMapper.latestVersion(wf).getId());assertEquals("v2.0",workflows.suggestVersionName(wf));assertEquals(2,workflowMapper.version(Long.parseLong(receipt.getString("workflowVersionId"))).getSnapshotRevision());
    }
    @Test void comparisonOnlyPersistsCandidateAndLeavesDraftAgentAndSelectedVersionUnchanged() {
        var agent=createAgent(canvas());long wf=agent.getLongValue("workflowId");var normal=workflows.createVersion(wf,space,0L,JSONObject.of("name","business"));var before=workflowMapper.find(wf);var beforeAgent=agentsMapper.find(agent.getLongValue("id"));var graph=canvas();params(graph).put("question","比较{{question}}");graph.put("compareOnlyNull",null);String comparison=UUID.randomUUID().toString();var body=JSONObject.of("flowId",agent.get("flowId"),"name","比较候选","data",graph,"version",comparison);
        var built=workflows.debugBuild(wf,space,1L,body,"comparison",comparison,"comparison_only_key");var snapshot=workflows.requireDebugReceipt(receipt(built),space);
        assertEquals("1",built.get("revision"));assertEquals("comparison",snapshot.mode());assertEquals(comparison,snapshot.comparisonId());assertEquals(before.getCanvasJson(),workflowMapper.find(wf).getCanvasJson());assertEquals(before.getName(),workflowMapper.find(wf).getName());assertEquals(before.getRevision(),workflowMapper.find(wf).getRevision());assertEquals(normal.getLong("id"),workflowMapper.find(wf).getLatestVersionId());assertEquals(beforeAgent.getRevision(),agentsMapper.find(beforeAgent.getId()).getRevision());assertEquals(beforeAgent.getConfigJson(),agentsMapper.find(beforeAgent.getId()).getConfigJson());assertTrue(snapshot.snapshot().canvas().containsKey("compareOnlyNull"));assertEquals("比较{{question}}",params(snapshot.snapshot().canvas()).get("question"));assertEquals(1,workflowMapper.countVersions(wf));
    }
    @Test void exactReplayReturnsOldFixedReceiptAfterLaterEditsAndNeverUpdatesAgain() {
        var agent=createAgent(canvas());long wf=agent.getLongValue("workflowId");var body=buildBody(agent,canvas());var first=workflows.debugBuild(wf,space,0L,body,"ordinary",null,"exact_replay_key");var oldHash=receipt(first).get("dslHash");workflows.save(wf,space,1L,JSONObject.of("description","later edit"));long agentRevision=agentsMapper.find(agent.getLongValue("id")).getRevision();
        var replay=workflows.debugBuild(wf,space,0L,body,"ordinary",null,"exact_replay_key");assertEquals(first,replay);assertEquals("1",replay.get("revision"));assertEquals(oldHash,receipt(replay).get("dslHash"));assertEquals(2,workflowMapper.find(wf).getRevision());assertEquals(agentRevision,agentsMapper.find(agent.getLongValue("id")).getRevision());assertEquals(1,rowsUnchecked("paiflow_workflow_version"));
    }
    @Test void sameKeyRejectsCanvasModeConditionWorkflowAndMissingVersusNullChanges() {
        var agent=createAgent(canvas());var body=buildBody(agent,canvas());long wf=agent.getLongValue("workflowId");workflows.debugBuild(wf,space,0L,body,"ordinary",null,"conflict_key_fixed");
        var changed=copy(body);changed.put("future",null);assertEquals(409,denied(()->workflows.debugBuild(wf,space,0L,changed,"ordinary",null,"conflict_key_fixed")));
        assertEquals(409,denied(()->workflows.debugBuild(wf,space,1L,body,"ordinary",null,"conflict_key_fixed")));
        assertEquals(409,denied(()->workflows.debugBuild(wf,space,0L,body,"comparison",UUID.randomUUID().toString(),"conflict_key_fixed")));
        var other=createAgent(canvas());assertEquals(409,denied(()->workflows.debugBuild(other.getLongValue("workflowId"),space,0L,buildBody(other,canvas()),"ordinary",null,"conflict_key_fixed")));assertEquals(1,rowsUnchecked("paiflow_workflow_version"));assertEquals(1,workflowMapper.find(wf).getRevision());assertEquals(0,workflowMapper.find(other.getLongValue("workflowId")).getRevision());
    }
    @Test void concurrentSameRequestProducesOnlyOneSaveAndOneVersion() throws Exception {
        var agent=createAgent(canvas());var body=buildBody(agent,canvas());long wf=agent.getLongValue("workflowId");var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);
        try {var a=pool.submit(()->{login();start.await();return workflows.debugBuild(wf,space,0L,copy(body),"ordinary",null,"concurrent_key");});var b=pool.submit(()->{login();start.await();return workflows.debugBuild(wf,space,0L,copy(body),"ordinary",null,"concurrent_key");});start.countDown();assertEquals(a.get(10,TimeUnit.SECONDS),b.get(10,TimeUnit.SECONDS));assertEquals(1,workflowMapper.find(wf).getRevision());assertEquals(2,agentsMapper.find(agent.getLongValue("id")).getRevision());assertEquals(1,rows("paiflow_workflow_version"));}finally{start.countDown();pool.shutdownNow();}
    }
    @Test void compilationFailureRollsBackOrdinaryDraftAndAgentSynchronization() {
        var agent=createAgent(canvas());long wf=agent.getLongValue("workflowId");String raw=workflowMapper.find(wf).getCanvasJson(),config=agentsMapper.find(agent.getLongValue("id")).getConfigJson();var invalid=canvas();invalid.getJSONArray("edges").getJSONObject(0).put("target","missing::node");
        assertEquals(422,denied(()->workflows.debugBuild(wf,space,0L,buildBody(agent,invalid),"ordinary",null,"invalid_compile_key")));assertEquals(raw,workflowMapper.find(wf).getCanvasJson());assertEquals(0,workflowMapper.find(wf).getRevision());assertEquals(1,agentsMapper.find(agent.getLongValue("id")).getRevision());assertEquals(config,agentsMapper.find(agent.getLongValue("id")).getConfigJson());assertEquals(0,rowsUnchecked("paiflow_workflow_version"));
    }
    @Test void agentMapperAndSnapshotMapperFailuresBothRollBackWholeBuild() throws Exception {
        var agent=createAgent(canvas());long wf=agent.getLongValue("workflowId");String original=workflowMapper.find(wf).getCanvasJson();assertEquals(0,sql("ALTER TABLE paiflow_agent ADD CONSTRAINT fixture_debug_agent CHECK(name<>'blocked_debug')"));var body=buildBody(agent,canvas());body.put("name","blocked_debug");assertThrows(RuntimeException.class,()->workflows.debugBuild(wf,space,0L,body,"ordinary",null,"blocked_agent_key"));assertEquals(0,workflowMapper.find(wf).getRevision());assertEquals(1,agentsMapper.find(agent.getLongValue("id")).getRevision());assertEquals(0,rows("paiflow_workflow_version"));
        assertEquals(0,sql("ALTER TABLE paiflow_workflow_version ADD CONSTRAINT fixture_debug_snapshot CHECK(debug_mode IS NULL)"));assertThrows(RuntimeException.class,()->ordinary(agent,canvas(),"blocked_snapshot_key"));assertEquals(original,workflowMapper.find(wf).getCanvasJson());assertEquals(0,workflowMapper.find(wf).getRevision());assertEquals(1,agentsMapper.find(agent.getLongValue("id")).getRevision());assertEquals(0,rows("paiflow_workflow_version"));
    }
    @Test void debugVersionsCannotBeListedSelectedViewedOrRestoredAsBusinessVersions() {
        var agent=createAgent(canvas());long wf=agent.getLongValue("workflowId");var built=ordinary(agent,canvas(),"private_debug_key");long v=Long.parseLong(receipt(built).getString("workflowVersionId"));assertEquals(0,workflows.versions(wf,space,1,10).total());assertNull(workflowMapper.latestVersion(wf));assertNull(workflowMapper.find(wf).getLatestVersionId());assertEquals("v1.0",workflows.suggestVersionName(wf));assertEquals(404,denied(()->workflows.versionDetail(v)));assertEquals(404,denied(()->workflows.restore(wf,v,space,1L)));assertEquals(1,workflowMapper.find(wf).getRevision());
    }
    @Test void receiptIsExactAndBindsActualVersionWorkflowFlowModeRevisionHashCodecAndKey() {
        var agent=createAgent(canvas());var built=ordinary(agent,canvas(),"receipt_binding_key");var original=receipt(built);assertEquals(10,original.size());var resolved=workflows.requireDebugReceipt(original,space);assertEquals(agent.getLong("id"),resolved.debugAgentId());assertEquals(original.getString("dslHash"),resolved.snapshot().dslHash());
        for(String key:original.keySet()){var changed=copy(original);changed.put(key,key.equals("comparisonId")?UUID.randomUUID().toString():"wrong");assertTrue(Set.of(400,404,409).contains(denied(()->workflows.requireDebugReceipt(changed,space))),key);var missing=copy(original);missing.remove(key);assertEquals(409,denied(()->workflows.requireDebugReceipt(missing,space)),key);}
        var extra=copy(original);extra.put("ownerUserId",42);assertEquals(409,denied(()->workflows.requireDebugReceipt(extra,space)));var numeric=copy(original);numeric.put("workflowVersionId",Long.parseLong(original.getString("workflowVersionId")));assertEquals(409,denied(()->workflows.requireDebugReceipt(numeric,space)));assertEquals(404,denied(()->workflows.requireDebugReceipt(original,space+100)));
    }
    @Test void debugOwnerDoesNotBecomeWorkflowOwnerOrAnotherMemberAndCurrentPermissionsAreRequired() throws Exception {
        var agent=createAgent(canvas());long wf=agent.getLongValue("workflowId");assertEquals(1,spaces.insertMember(space,43,3,"fixture"));assertEquals(1,sql("INSERT INTO sys_user_role VALUES(43,88)"));loginAs(43);var built=workflows.debugBuild(wf,space,0L,buildBody(agent,canvas()),"ordinary",null,"member_owner_key");var version=workflowMapper.version(Long.parseLong(receipt(built).getString("workflowVersionId")));assertEquals(42L,version.getOwnerUserId());assertEquals(43L,version.getDebugOwnerUserId());assertEquals(43L,identities.current().getUserId());
        login();assertEquals(403,denied(()->workflows.requireDebugReceipt(receipt(built),space)));assertEquals(403,denied(()->workflows.runtimeSnapshot(version.getId())));var own=workflows.debugBuild(wf,space,1L,buildBody(agent,canvas()),"ordinary",null,"member_owner_key");assertNotEquals(receipt(built).get("workflowVersionId"),receipt(own).get("workflowVersionId"));assertEquals(2,rows("paiflow_workflow_version"));loginAs(43);assertNotNull(workflows.requireDebugReceipt(receipt(built),space));revoke("paiflow:workflow:query");assertEquals(403,denied(()->workflows.requireDebugReceipt(receipt(built),space)));assertEquals(403,denied(()->workflows.runtimeSnapshot(version.getId())));
    }
    @Test void receiptRejectsDeletedOrReboundAgentButAllowsLaterDescriptionChanges() throws Exception {
        var agent=createAgent(canvas());long wf=agent.getLongValue("workflowId"),id=agent.getLongValue("id");var built=ordinary(agent,canvas(),"agent_tuple_key");workflows.save(wf,space,1L,JSONObject.of("description","later allowed"));assertNotNull(workflows.requireDebugReceipt(receipt(built),space));assertEquals(1,sql("UPDATE paiflow_agent SET deleted=1 WHERE id="+id));assertEquals(409,denied(()->workflows.requireDebugReceipt(receipt(built),space)));assertEquals(409,denied(()->workflows.runtimeSnapshot(Long.parseLong(receipt(built).getString("workflowVersionId")))));
    }
    @Test void missingRelationPortNeverClaimsUnboundAndActualUnboundWorkflowIsAllowed() {
        var unbound=workflows.create(space,JSONObject.of("name","unbound","data",canvas()));var body=JSONObject.of("id",unbound.get("id"),"flowId",unbound.get("flowId"),"name","unbound","data",canvas());var target=proxy(new WorkflowService(workflowMapper,access,identities));assertEquals(503,denied(()->target.debugBuild(unbound.getLongValue("id"),space,0L,body,"ordinary",null,"missing_port_key")));assertEquals(0,workflowMapper.find(unbound.getLongValue("id")).getRevision());assertEquals(0,rowsUnchecked("paiflow_workflow_version"));var built=workflows.debugBuild(unbound.getLongValue("id"),space,0L,body,"ordinary",null,"actual_unbound_key");assertNull(workflows.requireDebugReceipt(receipt(built),space).debugAgentId());
    }
    @Test void forgedOpaqueMetadataCannotDeclareReceiptOrSourceAndRawMetadataIsPreserved() throws Exception {
        var wf=workflows.create(space,JSONObject.of("name","opaque","data",canvas(),"debugReceipt",JSONObject.of("workflowVersionId","999"),"debugOwnerUserId",43,"future","keep"));long id=wf.getLongValue("id");assertFalse(workflows.detail(id,space).containsKey("debugReceipt"));assertFalse(workflows.detail(id,space).containsKey("debugOwnerUserId"));assertTrue(JSON.parseObject(workflowMapper.find(id).getMetadataJson()).containsKey("debugReceipt"));var body=JSONObject.of("id",id,"flowId",wf.get("flowId"),"name","opaque","data",canvas());var built=workflows.debugBuild(id,space,0L,body,"ordinary",null,"opaque_debug_key");assertEquals("42",String.valueOf(workflowMapper.version(Long.parseLong(receipt(built).getString("workflowVersionId"))).getDebugOwnerUserId()));body.put("debugReceipt",receipt(built));assertEquals(400,denied(()->workflows.debugBuild(id,space,1L,body,"ordinary",null,"forged_body_key")));
    }
    @Test void defaultScopeWireIsNullAndNamedHeaderCannotSelectDefaultOrOtherScope() {
        var agent=agents.legacyCreate("",3,JSONObject.of("name","default_debug","data",canvas().toJSONString(JSONWriter.Feature.WriteMapNullValue)));long wf=agent.getLongValue("workflowId");var built=facade.build(buildBody(agent,canvas()),"",0L,"default_build_key");assertNull(built.get("spaceId"));assertEquals("1",built.get("revision"));assertEquals(404,denied(()->facade.build(buildBody(agent,canvas()),Long.toString(space),0L,"wrong_scope_key")));assertEquals(1,workflowMapper.find(wf).getRevision());
    }
    @Test void databaseConstraintsRejectPartialNullDebugSourcesAndDuplicateOwnerKeys() throws Exception {
        var agent=createAgent(canvas());var built=ordinary(agent,canvas(),"constraint_owner_key");long version=Long.parseLong(receipt(built).getString("workflowVersionId"));assertThrows(java.sql.SQLException.class,()->sql("UPDATE paiflow_workflow_version SET debug_request_hash=NULL WHERE id="+version));assertThrows(java.sql.SQLException.class,()->sql("UPDATE paiflow_workflow_version SET debug_mode=NULL WHERE id="+version));assertThrows(java.sql.SQLException.class,()->sql("UPDATE paiflow_workflow_version SET debug_mode='ordinary',debug_comparison_id='"+UUID.randomUUID()+"' WHERE id="+version));assertEquals("ordinary",workflowMapper.version(version).getDebugMode());
        var duplicate=new com.ruoyi.paiflow.domain.WorkflowVersionRecord();org.springframework.beans.BeanUtils.copyProperties(workflowMapper.version(version),duplicate);duplicate.setId(null);duplicate.setVersionNum(UUID.randomUUID().toString());duplicate.setName("distinct_name_same_owner_key");assertThrows(RuntimeException.class,()->workflowMapper.insertVersion(duplicate));assertEquals(1,rows("paiflow_workflow_version"));
    }
    @Test void relationLookupWaitCannotReuseRevokedCurrentWorkflowEditPermission() throws Exception {
        var agent=createAgent(canvas());long wf=agent.getLongValue("workflowId");var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var actual=spy(new AgentService(agentsMapper,access,identities,workflows));actual.useDefaultSpaces(defaults);
        doAnswer(call->{Long relation=(Long)call.callRealMethod();entered.countDown();assertTrue(release.await(5,TimeUnit.SECONDS));return relation;}).when(actual).debugAgentId(any(),eq(true));var beans=new StaticListableBeanFactory();beans.addBean("actualDelayedRelation",actual);workflows.useAgentBindings(beans.getBeanProvider(WorkflowService.AgentBinding.class));var pool=Executors.newSingleThreadExecutor();
        try {var outcome=pool.submit(()->{login();return denied(()->workflows.debugBuild(wf,space,0L,buildBody(agent,canvas()),"ordinary",null,"revoked_after_wait_key"));});assertTrue(entered.await(5,TimeUnit.SECONDS));revoke("paiflow:workflow:edit");release.countDown();assertEquals(403,outcome.get(10,TimeUnit.SECONDS));assertEquals(0,workflowMapper.find(wf).getRevision());assertEquals(1,agentsMapper.find(agent.getLongValue("id")).getRevision());assertEquals(0,rows("paiflow_workflow_version"));}finally{release.countDown();pool.shutdownNow();}
    }
    private long rowsUnchecked(String table){try{return rows(table);}catch(Exception ex){throw new RuntimeException(ex);}}
}
